select * from rp_user_risk_data where 1=1

    and publish_date >=#{beginTime}
    and publish_date <= #{endTime}


    and date(publish_date) >=date(DATE_SUB(NOW(), INTERVAL 1 DAY))
    and date(publish_date) <= date(DATE_SUB(NOW(), INTERVAL 1 DAY))


    and brand_name = #{vo.brandName}


    and statistic_type = #{model.periodType}


